CREATE TYPE "CaseStatus" AS ENUM ('ACTIVE', 'WAITING', 'CLOSED');
CREATE TYPE "Priority" AS ENUM ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW');
CREATE TYPE "TaskStatus" AS ENUM ('OPEN', 'IN_PROGRESS', 'DONE');
CREATE TABLE "Case" ("id" TEXT NOT NULL,"number" SERIAL NOT NULL,"title" TEXT NOT NULL,"status" "CaseStatus" NOT NULL DEFAULT 'ACTIVE',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"summary" TEXT NOT NULL,"location" TEXT,"leadId" TEXT NOT NULL,"createdById" TEXT NOT NULL,"memberIds" JSONB NOT NULL DEFAULT '[]',"suspects" JSONB NOT NULL DEFAULT '[]',"victims" JSONB NOT NULL DEFAULT '[]',"witnesses" JSONB NOT NULL DEFAULT '[]',"evidence" JSONB NOT NULL DEFAULT '[]',"theories" JSONB NOT NULL DEFAULT '[]',"folders" JSONB NOT NULL DEFAULT '[]',"report" TEXT NOT NULL DEFAULT '',"reportUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Case_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Task" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"tag" TEXT NOT NULL DEFAULT 'ОБЩЕЕ',"dueAt" TIMESTAMP(3),"dueLabel" TEXT,"status" "TaskStatus" NOT NULL DEFAULT 'OPEN',"report" TEXT NOT NULL DEFAULT '',"assigneeId" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Task_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Informant" ("id" TEXT NOT NULL,"alias" TEXT NOT NULL,"realName" TEXT,"reliability" INTEGER NOT NULL DEFAULT 50,"area" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"specialties" TEXT NOT NULL,"notes" TEXT NOT NULL DEFAULT '',"lastContact" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Informant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Organization" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"zone" TEXT NOT NULL,"threat" TEXT NOT NULL,"members" INTEGER NOT NULL DEFAULT 0,"color" TEXT NOT NULL DEFAULT '#8e2f27',"notes" TEXT NOT NULL DEFAULT '',"people" JSONB NOT NULL DEFAULT '[]',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Case_number_key" ON "Case"("number"); CREATE INDEX "Case_status_idx" ON "Case"("status"); CREATE INDEX "Case_leadId_idx" ON "Case"("leadId");
CREATE INDEX "Task_status_idx" ON "Task"("status"); CREATE INDEX "Task_assigneeId_idx" ON "Task"("assigneeId");
CREATE UNIQUE INDEX "Informant_alias_key" ON "Informant"("alias"); CREATE UNIQUE INDEX "Organization_name_key" ON "Organization"("name");
ALTER TABLE "Case" ADD CONSTRAINT "Case_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Case" ADD CONSTRAINT "Case_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_assigneeId_fkey" FOREIGN KEY ("assigneeId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Task" ADD CONSTRAINT "Task_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
